using namespace std;

int main() {
    int T;
    cin >> T;

    while (T--) {
        int a, b, c;
        cin >> a >> b >> c;

        // 关键在于观察 k-xor 的性质
        // 由于 k-xor 是不进位加法，所以 c 的每一位的值
        // 不会超过 max(a, b) 的每一位的值
        int max_digit = max(a, b);
        int count = 0;
        for (int k = 2; k <= max_digit; ++k) {
            // 将 a 和 b 转换为 k 进制
            string a_str = to_string(a), b_str = to_string(b);
            string c_str = to_string(c);
            int a_len = a_str.size(), b_len = b_str.size();
            int c_len = c_str.size();

            // 逐位进行 k-xor
            int i = 0, j = 0, carry = 0;
            while (i < a_len || j < b_len || carry) {
                int sum = carry;
                if (i < a_len) sum += a_str[a_len - 1 - i] - '0';
                if (j < b_len) sum += b_str[b_len - 1 - j] - '0';
                sum %= k;
                carry = sum / k;
                if (i < a_len && j < b_len && c_str[c_len - 1 - i - j] != sum + '0') {
                    break;
                }
                i++;
                j++;
            }

            if (i == a_len && j == b_len && carry == 0) {
                count++;
            }
        }

        cout << count << endl;
    }

    return 0;
}
