        // 由于 k-xor 运算的性质，c 的每一位必须小于等于 a 和 b 的对应位之和。
        // 因此，我们可以枚举可能的 k 值，并判断 c 是否可以由 a 和 b 的 k-xor 运算得到。
        int count = 0;
        for (int k = 2; ; k++) {
            int x = a, y = b;
            int tempC = 0;
            while (x > 0 || y > 0 || tempC > 0) {
                int sum = (x % k + y % k + tempC) % k;
                tempC = (x % k + y % k + tempC) / k;
                x /= k;
                y /= k;
                if (sum != (c % k)) {
                    break;
                }
                c /= k;
            }
            if (tempC == 0) {
                count++;
            } else {
                break;
            }
        }
        cout << count << endl;
    }
    return 0;
}
