    int T;
    cin >> T;
    while (T--) {
        int a, b, c;
        cin >> a >> b >> c;

        // 思路：
        // 1. 由于 k-xor 是不进位加法，所以 c 的每一位必须小于等于 k-1。
        // 2. 我们可以枚举可能的 k，并判断 a 和 b 在 k 进制下的不进位加法是否等于 c。
        // 3. 如果满足条件，则 k 是一个可能的解。

        int count = 0;
        for (int k = 2; ; k++) {
            int x = a, y = b, z = c;
            while (x > 0 || y > 0 || z > 0) {
                int sum = (x % k + y % k + z % k) % k;
                x /= k;
                y /= k;
                z /= k;
