                a /= k;
                power *= k;
            }
            power = 1;
            while (b > 0) {
                b_k += (b % k) * power;
                b /= k;
                power *= k;
            }
            power = 1;
            while (c > 0) {
                c_k += (c % k) * power;
                c /= k;
                power *= k;
            }

