#include <iostream>
#include <algorithm>

using namespace std;

int main() {
  int T;
  cin >> T;
  while (T--) {
    int a, b, c;
    cin >> a >> b >> c;

    int count = 0;
    for (int k = 2; ; k++) {
      // 计算a和b在k进制下的k-xor
      int xor_result = 0;
      int a_k = a;
      int b_k = b;
      while (a_k > 0 || b_k > 0) {
        int a_digit = a_k % k;
        int b_digit = b_k % k;
        xor_result = (xor_result * k + (a_digit + b_digit) % k);
        a_k /= k;
        b_k /= k;
      }

      // 判断是否找到匹配的k
      if (xor_result == c) {
        count++;
      } else {
        break; // 如果没有找到匹配的k，则停止循环
      }
    }

    // 如果找到了无限多个k，输出-1
    if (count == 0) {
      cout << -1 << endl;
    } else {
      cout << count << endl;
    }
  }

  return 0;
}
