        int openBrackets = 0;

        for (int i = 1; i < n; i += 2) {
            if (s[i] == '(') {
                openBrackets++;
            } else {
                cost += openBrackets;
                openBrackets--;
            }
        }

        cout << cost << endl;
    }

    return 0;
}
